const { withAppDelegate, withInfoPlist } = require('@expo/config-plugins');

// SDK 56 uses the application lifecycle. Xcode 27 requires a scene-owned
// window to opt into the Duo's full display, including its side status area.
const LEGACY_WINDOW = /#if os\(iOS\) \|\| os\(tvOS\)\s+window = UIWindow\(frame: UIScreen\.main\.bounds\)\s+factory\.startReactNative\([\s\S]*?launchOptions: launchOptions\)\s+#endif/;
const SCENE_DELEGATE = `

// Model Pulse scene lifecycle (generated by with-ios-scene).
class ModelPulseSceneDelegate: UIResponder, UIWindowSceneDelegate {
  var window: UIWindow?

  func scene(_ scene: UIScene, willConnectTo session: UISceneSession,
             options connectionOptions: UIScene.ConnectionOptions) {
    guard let windowScene = scene as? UIWindowScene,
          let appDelegate = UIApplication.shared.delegate as? AppDelegate,
          let factory = appDelegate.reactNativeFactory else { return }
    let window = UIWindow(windowScene: windowScene)
    self.window = window
    appDelegate.window = window
    var launchOptions = appDelegate.modelPulseLaunchOptions ?? [:]
    if let context = connectionOptions.urlContexts.first {
      launchOptions[.url] = context.url
      if let source = context.options.sourceApplication {
        launchOptions[.sourceApplication] = source
      }
    }
    if let activity = connectionOptions.userActivities.first {
      launchOptions[.userActivityDictionary] = [
        "UIApplicationLaunchOptionsUserActivityKey": activity
      ]
    }
    factory.startReactNative(withModuleName: "main", in: window, launchOptions: launchOptions)
    window.makeKeyAndVisible()
  }

  func scene(_ scene: UIScene, openURLContexts contexts: Set<UIOpenURLContext>) {
    guard let delegate = UIApplication.shared.delegate as? AppDelegate else { return }
    for context in contexts {
      var options: [UIApplication.OpenURLOptionsKey: Any] = [
        .openInPlace: context.options.openInPlace
      ]
      if let source = context.options.sourceApplication { options[.sourceApplication] = source }
      if let annotation = context.options.annotation { options[.annotation] = annotation }
      _ = delegate.application(UIApplication.shared, open: context.url, options: options)
    }
  }

  func scene(_ scene: UIScene, continue userActivity: NSUserActivity) {
    guard let delegate = UIApplication.shared.delegate as? AppDelegate else { return }
    _ = delegate.application(UIApplication.shared, continue: userActivity, restorationHandler: { _ in })
  }

  func sceneDidBecomeActive(_ scene: UIScene) {
    (UIApplication.shared.delegate as? AppDelegate)?.applicationDidBecomeActive(UIApplication.shared)
  }

  func sceneWillResignActive(_ scene: UIScene) {
    (UIApplication.shared.delegate as? AppDelegate)?.applicationWillResignActive(UIApplication.shared)
  }

  func sceneDidEnterBackground(_ scene: UIScene) {
    (UIApplication.shared.delegate as? AppDelegate)?.applicationDidEnterBackground(UIApplication.shared)
  }

  func sceneWillEnterForeground(_ scene: UIScene) {
    (UIApplication.shared.delegate as? AppDelegate)?.applicationWillEnterForeground(UIApplication.shared)
  }
}
`;

function updateAppDelegate(source) {
  if (source.includes('class ModelPulseSceneDelegate:')) return source;
  if (!LEGACY_WINDOW.test(source)) throw new Error('with-ios-scene: SDK 56 window startup was not found; review the AppDelegate template.');
  return source
    .replace('var window: UIWindow?', 'var window: UIWindow?\n  var modelPulseLaunchOptions: [UIApplication.LaunchOptionsKey: Any]?')
    .replace('    let delegate = ReactNativeDelegate()', '    modelPulseLaunchOptions = launchOptions\n    let delegate = ReactNativeDelegate()')
    .replace(LEGACY_WINDOW, '// The scene delegate creates the window when its scene connects.') + SCENE_DELEGATE;
}

function withIosScene(config) {
  config = withInfoPlist(config, (config) => {
    config.modResults.UIApplicationSceneManifest = {
      UIApplicationSupportsMultipleScenes: false,
      UISceneConfigurations: {
        UIWindowSceneSessionRoleApplication: [{
          UISceneConfigurationName: 'Default Configuration',
          UISceneClassName: 'UIWindowScene',
          UISceneDelegateClassName: '$(PRODUCT_MODULE_NAME).ModelPulseSceneDelegate',
        }],
      },
    };
    return config;
  });
  return withAppDelegate(config, (config) => {
    if (config.modResults.language !== 'swift') throw new Error('with-ios-scene requires the Swift AppDelegate.');
    config.modResults.contents = updateAppDelegate(config.modResults.contents);
    return config;
  });
}

module.exports = withIosScene;
module.exports.updateAppDelegate = updateAppDelegate;
